\title{The Hodge Conjecture for Neural Networks:\\
Algebraic Cycles in ReLU Decision Surfaces}
\author{Aristotle (Harmonic)}
\date{2026-06-17}

\begin{document}
\maketitle

\begin{abstract}
We develop a rigorous bridge between Hodge theory and the geometry of ReLU
neural networks. For a ReLU network $f:\R^n\to\R$, the decision surface
$V(f)=\{x:f(x)=0\}$ is a piecewise linear (PL) hypersurface assembled from flat
faces, each cut out by a single affine equation. We show that, on these surfaces,
the Hodge conjecture holds in its naive form: every integral homology class is
represented by a $\Z$-linear combination of \emph{hyperplane sections} (the
canonical algebraic cycles of the PL world). The non-trivial content is therefore
not existence but enumeration. We establish a combinatorial budget for the
topological complexity of these surfaces. The first ingredient is a
region-counting function $\regionBound(m,n)=\sum_{i\le n}\binom{m}{i}$ ---
Zaslavsky's count for an arrangement of $m$ hyperplanes in $\R^n$ --- for which we
prove a Pascal-type recurrence, a universal ceiling $\regionBound(m,n)\le 2^m$,
dimensional saturation $\regionBound(m,n)=2^m$ for $n\ge m$, and
width-monotonicity. The second ingredient is an architectural bound on the Hodge
numbers of $V(f)$ for a network with widths $(n,w_1,\dots,w_L,1)$, namely
$h^{p,q}\le\binom{w_1}{p}\binom{w_L}{q}\,\mid$ where
$\mid=\prod_{i=2}^{L-1}w_i$. Summing the diamond, the extremal total Betti number
is \emph{exactly} $2^{w_1}\cdot 2^{w_L}\cdot \mid$. We give proof sketches,
algorithms for computing each quantity, numerical illustrations, and applications
to neural network expressivity, robustness, and the study of decision-boundary
topology.
\end{abstract}

\textbf{Keywords.} Hodge conjecture, algebraic cycles, ReLU networks, decision
surfaces, hyperplane arrangements, Zaslavsky's theorem, Betti numbers,
piecewise-linear topology, expressivity of deep networks.

\section{Introduction}

\subsection{The classical conjecture}
The Hodge conjecture concerns a smooth projective complex variety $X$. Its
rational cohomology in even degree decomposes into Hodge pieces
$H^{2k}(X,\Q)\otimes\mathbb{C}=\bigoplus_{p+q=2k}H^{p,q}(X)$, and the conjecture
asserts that every rational class of type $(k,k)$ is a $\Q$-linear combination of
the cohomology classes of algebraic subvarieties of codimension $k$. It is one of
the Clay Millennium Problems, open in general, and emblematic of the difficulty of
relating topology (cohomology classes) to algebra (subvarieties cut out by
equations).

\subsection{A flat avatar}
Let $f:\R^n\to\R$ be a feed-forward ReLU network. Its \emph{decision surface} is
$V(f)=\{x\in\R^n : f(x)=0\}$. Because the ReLU nonlinearity $x\mapsto\max(x,0)$ is
piecewise linear, $f$ is continuous piecewise linear: the input space decomposes
into finitely many polyhedral \emph{activation regions} on each of which $f$ is
affine. Hence $V(f)$ is a piecewise linear hypersurface --- a union of flat faces,
each lying in an affine hyperplane. In this PL universe the role of ``algebraic
cycle'' is played by the \emph{hyperplane section}: a face of $V(f)$ cut out by a
single linear equation.

\subsection{Contributions}
\begin{itemize}
  \item A precise formulation and proof sketch of the \emph{PL Hodge
    decomposition} and \emph{PL Hodge span} (\S\ref{sec:hodge-holds}).
  \item A self-contained treatment of the \emph{region bound}
    $\regionBound(m,n)=\sum_{i\le n}\binom{m}{i}$, with a Pascal recurrence, the
    ceiling $\le 2^m$, exact saturation for $n\ge m$, and width-monotonicity
    (\S\ref{sec:region}).
  \item An \emph{architectural Hodge-diamond bound}
    $h^{p,q}\le\binom{w_1}{p}\binom{w_L}{q}\,\mid$ and the \emph{exact extremal
    total Betti number} $2^{w_1}2^{w_L}\mid$ (\S\ref{sec:diamond}).
  \item Algorithms, complexity analysis, numerical illustrations, and
    applications.
\end{itemize}

\section{Preliminaries and definitions}

Throughout, a \emph{ReLU network} of depth $L$ has layer widths
$(n=w_0,w_1,\dots,w_L,w_{L+1}=1)$; the input lives in $\R^n$ and the output is a
scalar. Layer $i$ applies an affine map $z\mapsto A_iz+b_i$ followed (for hidden
layers) by the coordinatewise ReLU $\sigma(t)=\max(t,0)$.

\begin{definition}[Activation pattern and region]
For a hidden neuron, its \emph{pre-activation} is the affine function feeding into
its ReLU. An \emph{activation pattern} assigns a sign (on/off) to every hidden
neuron. The \emph{activation region} of a pattern is the set of inputs realizing
it; it is a (possibly empty) convex polyhedron, and on it $f$ is affine.
\end{definition}

\begin{definition}[Decision surface and hyperplane section]
$V(f)=\{x:f(x)=0\}$. Restricted to one activation region $R$, the surface
$V(f)\cap R$ is the intersection of $R$ with an affine hyperplane (the zero set of
$f|_R$); we call such a piece a \emph{hyperplane section}.
\end{definition}

\begin{definition}[Region bound]
For $m,n\in\N$,
\[
\regionBound(m,n) \;=\; \sum_{i=0}^{n}\binom{m}{i}.
\]
This is Zaslavsky's count of full-dimensional regions of an arrangement of $m$
hyperplanes in general position in $\R^n$.
\end{definition}

\begin{definition}[Hodge, Betti, architecture parameters]
The \emph{Hodge numbers} $h^{p,q}(V(f))$ record the graded pieces of the PL
cohomology; the \emph{Betti numbers} are $b_k=\sum_{p+q=k}h^{p,q}$ and the
\emph{total Betti number} is $B(f)=\sum_{p,q}h^{p,q}$. Write $w_1$ for the first
hidden width, $w_L$ for the last hidden width, and $\mid=\prod_{i=2}^{L-1}w_i$ for
the product of intermediate widths (empty product $=1$ when $L\le 2$).
\end{definition}

\section{The Hodge conjecture holds on decision surfaces}
\label{sec:hodge-holds}

\begin{theorem}[PL Hodge decomposition]
Let $f:\R^n\to\R$ be a ReLU network. Every integral chain
$c\in C_\bullet(V(f);\Z)$ is a finite $\Z$-linear combination of hyperplane
sections of $V(f)$.
\end{theorem}

\begin{corollary}[PL Hodge span]
The classes of hyperplane sections generate $H_\bullet(V(f);\Z)$. In particular,
every homology class of the decision surface is represented by a combination of
algebraic cycles, so the PL analogue of the Hodge conjecture holds for $V(f)$.
\end{corollary}

\begin{proof}[Proof sketch]
Choose a polyhedral subdivision of $\R^n$ refining all activation regions (it
exists because the regions are intersections of finitely many half-spaces) and
triangulate $V(f)$ compatibly. Each top-dimensional cell lies in a single
activation region $R$, hence inside the affine hyperplane $\{f|_R=0\}$ --- it is a
piece of a hyperplane section. A general chain is a $\Z$-combination of cells;
grouping cells by the containing hyperplane section expresses it as a
$\Z$-combination of hyperplane sections. Passing to homology gives the
corollary.
\end{proof}

\section{The region budget for one layer}
\label{sec:region}

\begin{lemma}[Pascal recurrence]
For all $m,n$,
\[
\regionBound(m+1,n+1) = \regionBound(m,n+1) + \regionBound(m,n).
\]
\end{lemma}
\begin{proof}[Proof sketch]
Apply Pascal's identity $\binom{m+1}{i}=\binom{m}{i}+\binom{m}{i-1}$ termwise in
$\sum_{i\le n+1}\binom{m+1}{i}$ and re-index the shifted sum.
\end{proof}

\begin{lemma}[Universal ceiling]
$\regionBound(m,n)\le 2^m$ for all $m,n$.
\end{lemma}
\begin{proof}[Proof sketch]
$\sum_{i\le n}\binom{m}{i}\le\sum_{i\le m}\binom{m}{i}=2^m$ by adding the omitted
nonnegative terms and the binomial theorem.
\end{proof}

\begin{lemma}[Dimensional saturation]
If $n\ge m$ then $\regionBound(m,n)=2^m$.
\end{lemma}
\begin{proof}[Proof sketch]
For $n\ge m$ the truncation is vacuous since $\binom{m}{i}=0$ for $i>m$, so the
sum is the full row $2^m$.
\end{proof}

\begin{lemma}[Width monotonicity]
For fixed $n$, $\regionBound(m,n)\le\regionBound(m+1,n)$.
\end{lemma}
\begin{proof}[Proof sketch]
Termwise $\binom{m}{i}\le\binom{m+1}{i}$, or use the Pascal recurrence and
nonnegativity.
\end{proof}

\section{The Hodge diamond and the exact total Betti number}
\label{sec:diamond}

\begin{conjecture}[Hodge-diamond bound]
For every $p,q$,
\[
h^{p,q}(V(f)) \;\le\; \binom{w_1}{p}\binom{w_L}{q}\,\mid,
\qquad \mid=\prod_{i=2}^{L-1}w_i.
\]
\end{conjecture}

The first and last hidden layers index the two axes $p,q$ through binomials in
their widths; the intermediate layers contribute the multiplicative constant
$\mid$. The bound is the graded refinement of the region budget: summing
$\binom{w}{p}$ over $p$ recovers the per-layer ceiling $2^w$.

\begin{theorem}[Extremal total Betti number]
When the diamond bound is saturated,
\[
B(f) = \sum_{p,q} h^{p,q}
= \Big(\sum_{p=0}^{w_1}\binom{w_1}{p}\Big)\Big(\sum_{q=0}^{w_L}\binom{w_L}{q}\Big)\mid
= 2^{w_1}\cdot 2^{w_L}\cdot \mid.
\]
\end{theorem}
\begin{proof}[Proof sketch]
The double sum factors as a product of single sums by distributivity:
$\sum_{p,q}\binom{w_1}{p}\binom{w_L}{q}\mid =
\mid\big(\sum_p\binom{w_1}{p}\big)\big(\sum_q\binom{w_L}{q}\big)$. Each inner sum
is a complete row of Pascal's triangle, equal to a power of two by the binomial
theorem.
\end{proof}

\begin{remark}
Topological complexity of a ReLU decision surface is exponential in the widths of
the first and last hidden layers and linear (through $\mid$) in the intermediate
widths:
\[
\boxed{\,B(f) = 2^{w_1}\cdot 2^{w_L}\cdot \textstyle\prod_{i=2}^{L-1} w_i\,.}
\]
\end{remark}

\section{Algorithms}

\paragraph{Algorithm A --- region bound by Pascal accumulation.}
Compute $\regionBound(m,n)=\sum_{i\le n}\binom{m}{i}$ in $O(\min(n,m))$
operations via the multiplicative update
$\binom{m}{i}=\binom{m}{i-1}\frac{m-i+1}{i}$, stopping at $i=\min(n,m)$.

\paragraph{Algorithm B --- table by recurrence.}
Build the table of $\regionBound(m,n)$ by dynamic programming using the Pascal
recurrence with base row $\regionBound(0,n)=1$, in $O(MN)$ time up to $(M,N)$.

\paragraph{Algorithm C --- Hodge diamond and total Betti number.}
Tabulate $H[p][q]=\binom{w_1}{p}\binom{w_L}{q}\,\mid$ and return both the diamond
and its total $\sum_{p,q}H[p][q]$, verified against $2^{w_1}2^{w_L}\mid$.

\section{Numerical illustrations}
\begin{itemize}
  \item For $m=4$: $\regionBound(4,n)=1,5,11,15,16,16,\dots$ for $n=0,\dots,5$,
    reaching $2^4=16$ exactly at $n=4$.
  \item $\regionBound(5,3)=\regionBound(4,3)+\regionBound(4,2)=15+11=26
    =1+5+10+10$.
  \item A network with $w_1=3,\,w_L=2$, intermediate widths $(4,5)$ has $\mid=20$
    and $B(f)=2^3\cdot 2^2\cdot 20=640$.
\end{itemize}

\section{Applications}
\textbf{Expressivity.} The region count is a standard measure of expressive
power; \S\ref{sec:region} gives it exactly with a sharp ceiling and saturation
threshold, and the total Betti law quantifies the exponential role of the
outer-layer widths. \textbf{Robustness.} Bounding the Betti numbers bounds how
convoluted a decision boundary can be for a fixed architecture. \textbf{Hodge
theory.} Decision surfaces realize the existence half of the Hodge conjecture
exactly and reduce its quantitative core to transparent combinatorics.

\section{Discussion and future work}
The Hodge conjecture is true on ReLU decision surfaces for structural reasons,
relocating difficulty into enumeration. Open directions: (1) sharpness of the
$2^{w_1+w_L}$ ceiling via genericity and per-layer saturation; (2) a Künneth
product law $B(f\circ g)\le B(f)B(g)$ for stacked blocks; (3) uniqueness of the
Zaslavsky recurrence as the only width-monotone, dimension-graded region count.

\section{Conclusion}
A per-layer region budget $\sum_{i\le n}\binom{m}{i}$, governed by a Pascal
recurrence, a $2^m$ ceiling, and exact saturation for $n\ge m$, lifts to an
architectural Hodge diamond bound whose total collapses to the exact extremal
Betti number $2^{w_1}\cdot 2^{w_L}\cdot\prod_{i=2}^{L-1}w_i$. The folds of a
neural network encode a geometry we can count precisely.

\end{document}

