function REGION_BOUND_TABLE(M, N):
    allocate R[0..M][0..N]
    for n from 0 to N: R[0][n] <- 1          # zero hyperplanes -> one region
    for m from 1 to M:
        R[m][0] <- 1
        for n from 1 to N:
            R[m][n] <- R[m-1][n] + R[m-1][n-1]
    return R

function HODGE_DIAMOND_AND_BETTI(w1, wL, mid):
    diamond <- matrix of size (w1+1) x (wL+1)
    for p from 0 to w1:
        for q from 0 to wL:
            diamond[p][q] <- C(w1,p) * C(wL,q) * mid
    total <- sum of all entries of diamond
    assert total == 2^{w1} * 2^{wL} * mid
    return (diamond, total)
